// UI translations: Spanish (default), English, German, Brazilian Portuguese, Simplified Chinese and Russian.
// Names of items, systems and pilots come from ESI and aren't translated;
// the k / M / B ISK notation is the game's and is kept in every language
import type { AstroGlobal } from 'astro';
import type { Activity } from './api';

export const LANGS = ['es', 'en', 'de', 'pt', 'zh', 'ru'] as const;
export type Lang = (typeof LANGS)[number];
export const DEFAULT_LANG: Lang = 'es';
export const LANG_COOKIE = 'lang';
export const LANG_NAMES: Record<Lang, string> = {
  es: 'Español',
  en: 'English',
  de: 'Deutsch',
  pt: 'Português (Brasil)',
  zh: '简体中文',
  ru: 'Русский',
};
// BCP 47 tag for <html lang>, hreflang and Intl (the region picks Brazilian Portuguese and Simplified Chinese)
export const LANG_TAGS: Record<Lang, string> = { es: 'es', en: 'en', de: 'de', pt: 'pt-BR', zh: 'zh-CN', ru: 'ru' };

export const isLang = (v: unknown): v is Lang => typeof v === 'string' && (LANGS as readonly string[]).includes(v);

// Request language: the selector's cookie or the default
export function getLang(astro: Pick<AstroGlobal, 'cookies'>): Lang {
  const v = astro.cookies.get(LANG_COOKIE)?.value;
  return isLang(v) ? v : DEFAULT_LANG;
}

// Language for a page opened in the system browser (without the dashboard cookie): the browser's
export function getRequestLang(astro: Pick<AstroGlobal, 'cookies' | 'request'>): Lang {
  const v = astro.cookies.get(LANG_COOKIE)?.value;
  if (isLang(v)) return v;
  const accepted = (astro.request.headers.get('accept-language') ?? '').split(',').map((l) => l.trim().slice(0, 2).toLowerCase());
  return accepted.find(isLang) ?? DEFAULT_LANG;
}

const plural = (n: number, one: string, many: string) => (n === 1 ? one : many);
// Russian: 1, 21… / 2–4, 22–24… / the rest, with 11–14 always in the last form
const pluralRu = (n: number, one: string, few: string, many: string) => {
  const a = Math.abs(n) % 100,
    b = a % 10;
  return a > 10 && a < 15 ? many : b === 1 ? one : b >= 2 && b <= 4 ? few : many;
};

